from pathlib import Path
import subprocess
import sys
import unittest

from test_duration import INVALID_DURATIONS, VALID_DURATIONS


CLI_PATH = Path(__file__).resolve().with_name("cli.py")


class CliTests(unittest.TestCase):
    def run_cli(self, *args):
        return subprocess.run(
            [sys.executable, str(CLI_PATH), *args],
            capture_output=True,
            text=True,
            timeout=5,
        )

    def assert_cli_error(self, result):
        self.assertEqual(result.returncode, 2)
        self.assertEqual(result.stdout, "")
        self.assertIn("error", result.stderr.lower())
        self.assertIn("duration", result.stderr.lower())
        self.assertNotIn("Traceback", result.stderr)

    def test_valid_durations(self):
        for text, expected in VALID_DURATIONS.items():
            with self.subTest(text=text):
                result = self.run_cli(text)
                self.assertEqual(result.returncode, 0)
                self.assertEqual(result.stdout, f"{expected}\n")
                self.assertEqual(result.stderr, "")

    def test_invalid_durations(self):
        for text in INVALID_DURATIONS:
            with self.subTest(text=text):
                self.assert_cli_error(self.run_cli(text))

    def test_missing_argument(self):
        self.assert_cli_error(self.run_cli())

    def test_extra_argument(self):
        self.assert_cli_error(self.run_cli("1s", "2m"))


if __name__ == "__main__":
    unittest.main()
